import React, { useEffect, useState } from "react";
import AdminProtectedRoute from "../components/adminProtectedRoute";
import { auth } from "../../firebaseConfig";
import { signOut } from "firebase/auth";
import { graphql, navigate } from "gatsby";
import {
  collection,
  getDocs,
  QueryDocumentSnapshot,
  deleteDoc,
  doc,
} from "firebase/firestore";
import { db } from "../../firebaseConfig";
import { useTranslation } from "gatsby-plugin-react-i18next";

type PartnerRecord = {
  id: string;
  category?: string;
  name?: string;
  address?: string;
  email?: string;
  telephone?: string;
  productInterest?: string;
  createdAt?: { seconds: number; nanoseconds: number };
};

type ContactRecord = {
  id: string;
  fullName?: string;
  email?: string;
  message?: string;
  createdAt?: { seconds: number; nanoseconds: number };
};

type SubscribeRecord = {
  id: string;
  email?: string;
  createdAt?: { seconds: number; nanoseconds: number };
};

type TableColumn = {
  key: string;
  label: string;
};

type TableRow = Record<string, React.ReactNode>;

type RecordsTableProps = {
  title: string;
  loadingText: string;
  emptyText: string;
  errorText: string;
  columns: TableColumn[];
  rows: TableRow[];
  isLoading: boolean;
  hasError: boolean;
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  paginationText: string;
  previousLabel: string;
  nextLabel: string;
};

const RecordsTable = ({
  title,
  loadingText,
  emptyText,
  errorText,
  columns,
  rows,
  isLoading,
  hasError,
  currentPage,
  totalPages,
  onPageChange,
  paginationText,
  previousLabel,
  nextLabel,
}: RecordsTableProps) => {
  return (
    <div className="mb-10">
      <div className="mb-4 text-sm font-semibold">{title}</div>

      {isLoading && (
        <div className="text-sm text-DarkGrayText">{loadingText}</div>
      )}
      {!isLoading && hasError && (
        <div className="text-sm text-Red">{errorText}</div>
      )}
      {!isLoading && !hasError && rows.length === 0 && (
        <div className="text-sm text-DarkGrayText">{emptyText}</div>
      )}

      {!isLoading && !hasError && rows.length > 0 && (
        <>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm border-collapse">
              <thead>
                <tr className="border-b border-LightGrayText">
                  {columns.map((column) => (
                    <th key={column.key} className="py-2 pr-3">
                      {column.label}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {rows.map((row, index) => (
                  <tr key={index} className="border-b border-LightGrayText/20">
                    {columns.map((column) => (
                      <td key={column.key} className="py-2 pr-3">
                        {row[column.key] || "-"}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {totalPages > 1 && (
            <div className="mt-4 flex items-center justify-end gap-3 text-sm">
              <span className="text-DarkGrayText">{paginationText}</span>
              <button
                type="button"
                onClick={() => onPageChange(Math.max(1, currentPage - 1))}
                className="rounded-md border border-LightGrayText px-3 py-1 text-DarkGreen hover:border-Yellow disabled:opacity-40"
                disabled={currentPage === 1}
              >
                {previousLabel}
              </button>
              <button
                type="button"
                onClick={() => onPageChange(Math.min(totalPages, currentPage + 1))}
                className="rounded-md border border-LightGrayText px-3 py-1 text-DarkGreen hover:border-Yellow disabled:opacity-40"
                disabled={currentPage === totalPages}
              >
                {nextLabel}
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
};

const AdminPage = () => {
  const { t } = useTranslation();
  const pageSize = 10;
  const [partnersRecords, setPartnersRecords] = useState<PartnerRecord[]>([]);
  const [contactRecords, setContactRecords] = useState<ContactRecord[]>([]);
  const [subscribeRecords, setSubscribeRecords] = useState<SubscribeRecord[]>([]);
  const [loadingRecords, setLoadingRecords] = useState(true);
  const [loadingContactRecords, setLoadingContactRecords] = useState(true);
  const [loadingSubscribeRecords, setLoadingSubscribeRecords] = useState(true);
  const [recordsError, setRecordsError] = useState("");
  const [contactRecordsError, setContactRecordsError] = useState("");
  const [subscribeRecordsError, setSubscribeRecordsError] = useState("");
  const [partnersPage, setPartnersPage] = useState(1);
  const [contactPage, setContactPage] = useState(1);
  const [subscribePage, setSubscribePage] = useState(1);
  const [activeTab, setActiveTab] = useState<"partners" | "contacts" | "subscribe">(
    "partners"
  );
  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null);
  const [pendingDeleteCollection, setPendingDeleteCollection] = useState<
    "contactMessages" | "subscribeForm" | null
  >(null);

  useEffect(() => {
    const fetchRecords = async () => {
      try {
        const snapshot = await getDocs(collection(db, "partnersForm"));
        const rows = snapshot.docs.map((doc: QueryDocumentSnapshot) => ({
          id: doc.id,
          ...(doc.data() as Omit<PartnerRecord, "id">),
        }));
        setPartnersRecords(rows);
      } catch (error) {
        console.error("Error loading partners form records:", error);
        setRecordsError(t("admin.errors.loadRecords") || "Unable to load records.");
      } finally {
        setLoadingRecords(false);
      }
    };

    fetchRecords();
  }, [t]);

  useEffect(() => {
    const fetchContactRecords = async () => {
      try {
        const snapshot = await getDocs(collection(db, "contactMessages"));
        const rows = snapshot.docs.map((doc: QueryDocumentSnapshot) => ({
          id: doc.id,
          ...(doc.data() as Omit<ContactRecord, "id">),
        }));
        setContactRecords(rows);
      } catch (error) {
        console.error("Error loading contact records:", error);
        setContactRecordsError(
          t("admin.errors.loadContactRecords") || "Unable to load records."
        );
      } finally {
        setLoadingContactRecords(false);
      }
    };

    fetchContactRecords();
  }, [t]);

  useEffect(() => {
    const fetchSubscribeRecords = async () => {
      try {
        const snapshot = await getDocs(collection(db, "subscribeForm"));
        const rows = snapshot.docs.map((doc: QueryDocumentSnapshot) => ({
          id: doc.id,
          ...(doc.data() as Omit<SubscribeRecord, "id">),
        }));
        setSubscribeRecords(rows);
      } catch (error) {
        console.error("Error loading subscribe records:", error);
        setSubscribeRecordsError(
          t("admin.errors.loadSubscribeRecords") || "Unable to load records."
        );
      } finally {
        setLoadingSubscribeRecords(false);
      }
    };

    fetchSubscribeRecords();
  }, [t]);

  const formatDate = (createdAt?: { seconds: number; nanoseconds: number }) => {
    if (!createdAt?.seconds) return "-";
    const date = new Date(createdAt.seconds * 1000);
    return date.toLocaleString("en-US", {
      month: "long",
      day: "numeric",
      year: "numeric",
      hour: "numeric",
      minute: "2-digit",
      hour12: true,
    });
  };

  const createdAtSeconds = (
    createdAt?: { seconds: number; nanoseconds: number }
  ) => createdAt?.seconds || 0;

  const paginateRows = (rows: TableRow[], page: number) => {
    const start = (page - 1) * pageSize;
    return rows.slice(start, start + pageSize);
  };

  const handleLogout = async () => {
    await signOut(auth);
    navigate("/login");
  };

  const handleDeleteContact = async (id: string) => {
    try {
      await deleteDoc(doc(db, "contactMessages", id));
      setContactRecords((prev) => prev.filter((record) => record.id !== id));
    } catch (error) {
      console.error("Error deleting contact message:", error);
      setContactRecordsError(
        t("admin.errors.deleteContactRecord") || "Unable to delete record."
      );
    }
  };

  const handleDeleteSubscribe = async (id: string) => {
    try {
      await deleteDoc(doc(db, "subscribeForm", id));
      setSubscribeRecords((prev) => prev.filter((record) => record.id !== id));
    } catch (error) {
      console.error("Error deleting subscribe record:", error);
      setSubscribeRecordsError(
        t("admin.errors.deleteSubscribeRecord") || "Unable to delete record."
      );
    }
  };

  const partnersColumns: TableColumn[] = [
    {
      key: "category",
      label: t("admin.partnersForm.columns.category") || "Category",
    },
    { key: "name", label: t("admin.partnersForm.columns.name") || "Name" },
    {
      key: "address",
      label: t("admin.partnersForm.columns.address") || "Address",
    },
    { key: "email", label: t("admin.partnersForm.columns.email") || "Email" },
    {
      key: "telephone",
      label: t("admin.partnersForm.columns.telephone") || "Telephone",
    },
    {
      key: "productInterest",
      label:
        t("admin.partnersForm.columns.productInterest") || "Product Interest",
    },
    {
      key: "createdAt",
      label: t("admin.partnersForm.columns.createdAt") || "Created At",
    },
  ];

  const sortedPartners = [...partnersRecords].sort(
    (a, b) => createdAtSeconds(b.createdAt) - createdAtSeconds(a.createdAt)
  );

  const partnersRows: TableRow[] = sortedPartners.map((record) => ({
    category: record.category || "-",
    name: record.name || "-",
    address: record.address || "-",
    email: record.email || "-",
    telephone: record.telephone || "-",
    productInterest: record.productInterest || "-",
    createdAt: formatDate(record.createdAt),
  }));

  const partnersTotalPages = Math.max(
    1,
    Math.ceil(partnersRows.length / pageSize)
  );
  const partnersPageRows = paginateRows(partnersRows, partnersPage);

  const contactColumns: TableColumn[] = [
    {
      key: "fullName",
      label: t("admin.contactMessages.columns.fullName") || "Name",
    },
    {
      key: "email",
      label: t("admin.contactMessages.columns.email") || "Email",
    },
    {
      key: "message",
      label: t("admin.contactMessages.columns.message") || "Message",
    },
    {
      key: "createdAt",
      label: t("admin.contactMessages.columns.createdAt") || "Created At",
    },
    {
      key: "actions",
      label: t("admin.contactMessages.columns.actions") || "Actions",
    },
  ];

  const sortedContacts = [...contactRecords].sort(
    (a, b) => createdAtSeconds(b.createdAt) - createdAtSeconds(a.createdAt)
  );

  const contactRows: TableRow[] = sortedContacts.map((record) => ({
    fullName: record.fullName || "-",
    email: record.email || "-",
    message: record.message || "-",
    createdAt: formatDate(record.createdAt),
    actions: (
      <button
        type="button"
        onClick={() => {
          setPendingDeleteId(record.id);
          setPendingDeleteCollection("contactMessages");
        }}
        className="inline-flex items-center justify-center rounded-md border border-LightGrayText px-2 py-1 text-DarkGreen hover:border-Red hover:text-Red"
        aria-label={t("admin.contactMessages.actions.remove") || "Remove"}
        title={t("admin.contactMessages.actions.remove") || "Remove"}
      >
        <svg
          viewBox="0 0 24 24"
          width="16"
          height="16"
          aria-hidden="true"
          className="fill-current"
        >
          <path d="M9 3h6l1 2h4v2H4V5h4l1-2zm1 6h2v9h-2V9zm4 0h2v9h-2V9zM7 9h2v9H7V9z" />
        </svg>
      </button>
    ),
  }));

  const contactTotalPages = Math.max(
    1,
    Math.ceil(contactRows.length / pageSize)
  );
  const contactPageRows = paginateRows(contactRows, contactPage);

  const subscribeColumns: TableColumn[] = [
    {
      key: "email",
      label: t("admin.subscribeForm.columns.email") || "Email",
    },
    {
      key: "createdAt",
      label: t("admin.subscribeForm.columns.createdAt") || "Created At",
    },
    {
      key: "actions",
      label: t("admin.subscribeForm.columns.actions") || "Actions",
    },
  ];

  const sortedSubscribes = [...subscribeRecords].sort(
    (a, b) => createdAtSeconds(b.createdAt) - createdAtSeconds(a.createdAt)
  );

  const subscribeRows: TableRow[] = sortedSubscribes.map((record) => ({
    email: record.email || "-",
    createdAt: formatDate(record.createdAt),
    actions: (
      <button
        type="button"
        onClick={() => {
          setPendingDeleteId(record.id);
          setPendingDeleteCollection("subscribeForm");
        }}
        className="inline-flex items-center justify-center rounded-md border border-LightGrayText px-2 py-1 text-DarkGreen hover:border-Red hover:text-Red"
        aria-label={t("admin.subscribeForm.actions.remove") || "Remove"}
        title={t("admin.subscribeForm.actions.remove") || "Remove"}
      >
        <svg
          viewBox="0 0 24 24"
          width="16"
          height="16"
          aria-hidden="true"
          className="fill-current"
        >
          <path d="M9 3h6l1 2h4v2H4V5h4l1-2zm1 6h2v9h-2V9zm4 0h2v9h-2V9zM7 9h2v9H7V9z" />
        </svg>
      </button>
    ),
  }));

  const subscribeTotalPages = Math.max(
    1,
    Math.ceil(subscribeRows.length / pageSize)
  );
  const subscribePageRows = paginateRows(subscribeRows, subscribePage);

  useEffect(() => {
    setPartnersPage((page) => Math.min(page, partnersTotalPages));
  }, [partnersTotalPages]);

  useEffect(() => {
    setContactPage((page) => Math.min(page, contactTotalPages));
  }, [contactTotalPages]);

  useEffect(() => {
    setSubscribePage((page) => Math.min(page, subscribeTotalPages));
  }, [subscribeTotalPages]);

  return (
    <AdminProtectedRoute>
      <div className="min-h-screen bg-DarkGreen py-10">
        <div className="max-w-6xl mx-auto px-4">
          <div className="bg-MidGray p-6 rounded-lg shadow-md border border-LightGrayText text-DarkGreen">
            <div className="flex items-center justify-between mb-6">
              <div className="text-lg font-semibold">
                {t("admin.title") || "Admin"}
              </div>
              <button
                type="button"
                onClick={handleLogout}
                className="border body-mob sm:body !backdrop-blur-md rounded-lg py-2 px-4 border-LightGrayText hover:border-Yellow bg-white/10 hover:bg-white/20 active:bg-Yellow active:border-LightGrayText active:text-DarkGreen"
              >
                {t("admin.logout") || "Logout"}
              </button>
            </div>

            <div className="mb-6 flex flex-wrap gap-2">
              <button
                type="button"
                onClick={() => setActiveTab("partners")}
                className={`rounded-full border px-4 py-2 text-sm ${
                  activeTab === "partners"
                    ? "border-Yellow text-DarkGreen"
                    : "border-LightGrayText text-DarkGreen/70"
                }`}
              >
                {t("admin.tabs.partners") || "Partners Form"}
              </button>
              <button
                type="button"
                onClick={() => setActiveTab("contacts")}
                className={`rounded-full border px-4 py-2 text-sm ${
                  activeTab === "contacts"
                    ? "border-Yellow text-DarkGreen"
                    : "border-LightGrayText text-DarkGreen/70"
                }`}
              >
                {t("admin.tabs.contacts") || "Contact Messages"}
              </button>
              <button
                type="button"
                onClick={() => setActiveTab("subscribe")}
                className={`rounded-full border px-4 py-2 text-sm ${
                  activeTab === "subscribe"
                    ? "border-Yellow text-DarkGreen"
                    : "border-LightGrayText text-DarkGreen/70"
                }`}
              >
                {t("admin.tabs.subscribe") || "Subscribe Form"}
              </button>
            </div>

            {activeTab === "partners" && (
              <RecordsTable
                title={t("admin.partnersForm.title") || "Partners Form"}
                loadingText={
                  t("admin.partnersForm.loading") || "Loading records..."
                }
                emptyText={t("admin.partnersForm.empty") || "No records yet."}
                errorText={recordsError}
                columns={partnersColumns}
                rows={partnersPageRows}
                isLoading={loadingRecords}
                hasError={!!recordsError}
                currentPage={partnersPage}
                totalPages={partnersTotalPages}
                onPageChange={setPartnersPage}
                paginationText={
                  t("admin.pagination.pageOf", {
                    current: partnersPage,
                    total: partnersTotalPages,
                  }) || `Page ${partnersPage} of ${partnersTotalPages}`
                }
                previousLabel={t("admin.pagination.previous") || "Previous"}
                nextLabel={t("admin.pagination.next") || "Next"}
              />
            )}

            {activeTab === "contacts" && (
              <RecordsTable
                title={t("admin.contactMessages.title") || "Contact Messages"}
                loadingText={
                  t("admin.contactMessages.loading") || "Loading records..."
                }
                emptyText={t("admin.contactMessages.empty") || "No records yet."}
                errorText={contactRecordsError}
                columns={contactColumns}
                rows={contactPageRows}
                isLoading={loadingContactRecords}
                hasError={!!contactRecordsError}
                currentPage={contactPage}
                totalPages={contactTotalPages}
                onPageChange={setContactPage}
                paginationText={
                  t("admin.pagination.pageOf", {
                    current: contactPage,
                    total: contactTotalPages,
                  }) || `Page ${contactPage} of ${contactTotalPages}`
                }
                previousLabel={t("admin.pagination.previous") || "Previous"}
                nextLabel={t("admin.pagination.next") || "Next"}
              />
            )}

            {activeTab === "subscribe" && (
              <RecordsTable
                title={t("admin.subscribeForm.title") || "Subscribe Form"}
                loadingText={
                  t("admin.subscribeForm.loading") || "Loading records..."
                }
                emptyText={t("admin.subscribeForm.empty") || "No records yet."}
                errorText={subscribeRecordsError}
                columns={subscribeColumns}
                rows={subscribePageRows}
                isLoading={loadingSubscribeRecords}
                hasError={!!subscribeRecordsError}
                currentPage={subscribePage}
                totalPages={subscribeTotalPages}
                onPageChange={setSubscribePage}
                paginationText={
                  t("admin.pagination.pageOf", {
                    current: subscribePage,
                    total: subscribeTotalPages,
                  }) || `Page ${subscribePage} of ${subscribeTotalPages}`
                }
                previousLabel={t("admin.pagination.previous") || "Previous"}
                nextLabel={t("admin.pagination.next") || "Next"}
              />
            )}
          </div>
        </div>
      </div>
      {pendingDeleteId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
          <div className="w-full max-w-md rounded-lg border border-LightGrayText bg-MidGray p-6 text-DarkGreen shadow-md">
            <div className="mb-2 text-lg font-semibold">
              {pendingDeleteCollection === "subscribeForm"
                ? t("admin.subscribeForm.confirm.title") || "Confirm deletion"
                : t("admin.contactMessages.confirm.title") || "Confirm deletion"}
            </div>
            <div className="mb-6 text-sm text-DarkGrayText">
              {pendingDeleteCollection === "subscribeForm"
                ? t("admin.subscribeForm.confirm.body") ||
                  "This action cannot be undone."
                : t("admin.contactMessages.confirm.body") ||
                  "This action cannot be undone."}
            </div>
            <div className="flex items-center justify-end gap-3">
              <button
                type="button"
                onClick={() => {
                  setPendingDeleteId(null);
                  setPendingDeleteCollection(null);
                }}
                className="rounded-md border border-LightGrayText px-4 py-2 text-DarkGreen hover:border-Yellow"
              >
                {pendingDeleteCollection === "subscribeForm"
                  ? t("admin.subscribeForm.confirm.cancel") || "Cancel"
                  : t("admin.contactMessages.confirm.cancel") || "Cancel"}
              </button>
              <button
                type="button"
                onClick={() => {
                  const id = pendingDeleteId;
                  const collectionName = pendingDeleteCollection;
                  setPendingDeleteId(null);
                  setPendingDeleteCollection(null);
                  if (collectionName === "subscribeForm") {
                    handleDeleteSubscribe(id);
                  } else {
                    handleDeleteContact(id);
                  }
                }}
                className="rounded-md border border-Red bg-Red/10 px-4 py-2 text-Red hover:bg-Red/20"
              >
                {pendingDeleteCollection === "subscribeForm"
                  ? t("admin.subscribeForm.confirm.confirm") || "Delete"
                  : t("admin.contactMessages.confirm.confirm") || "Delete"}
              </button>
            </div>
          </div>
        </div>
      )}
    </AdminProtectedRoute>
  );
};

export default AdminPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
